input.command:
B=/workspace/dataset/test11_executable
p(){ printf '%-24s|%s|%s|\n' "$1" "$($B 1 "$1" | sed -n '3p')" "$($B 1 "$1" | sed -n '4p')"; }
for w in '' '_' '__' '___' 'a' 'A' '_a' 'a_' 'a_b' 'a__b' '__double__' 'ab_cd_' 'x__y__z' 'CamelCase' 'UPPER' 'UPPER_CASE' 'FOO_bar' 'my-word' 'a/b_c' 'a::b_c' 'ZZ_zz' '_leading'; do p "$w"; done

perl -e '
my $B="/workspace/dataset/test11_executable";
sub camel { my ($s,$lf)=@_; my @b=unpack("C*",$s); my $cap=$lf?0:1; my $i=0;
  while($i<scalar(@b)){ if($b[$i]==0x5f){ $cap=1; splice(@b,$i,1); next; }
    if($cap){ if($b[$i]>=0x61 && $b[$i]<=0x7a){ $b[$i]-=32; } $cap=0; } $i++; }
  return pack("C*",@b); }
srand(4242);
my @pool=(0x5f,0x5f,0x5f,0x2d,0x20,0x2f,0x3a,0x2e,0x39,0x30,0x41,0x5a,0x61,0x7a,0x62,0x42,0xc3,0xa9,0xff,0x80,0x7f,0x01,0x09,0x7b,0x60,0xdf,0xe9,0xd0,0xb0);
my $bad=0; my $firstbyte_viol=0; my $n=0;
for my $t (1..250){
  my $len=int(rand(9));
  my $w=""; for (1..$len){ $w.=chr($pool[int(rand(scalar @pool))]); }
  open(my $fh, "-|", $B, "1", $w) or die; my @lines=<$fh>; close $fh;
  chomp(my $l3=$lines[2]); chomp(my $l4=$lines[3]);
  my $e3=camel($w,1); my $e4=camel($w,0);
  $n++;
  if($l3 ne $e3 || $l4 ne $e4){ $bad++; printf("MISMATCH w=%s got3=%s exp3=%s got4=%s exp4=%s\n", unpack("H*",$w), unpack("H*",$l3), unpack("H*",$e3), unpack("H*",$l4), unpack("H*",$e4)); }
  # first-byte-only difference claim
  if(length($l3)!=length($l4)){ printf("LENDIFF w=%s\n",unpack("H*",$w)); $firstbyte_viol++; }
  elsif(length($l3)>1 && substr($l3,1) ne substr($l4,1)){ printf("TAILDIFF w=%s\n",unpack("H*",$w)); $firstbyte_viol++; }
}
print "tested=$n mismatches=$bad tailviol=$firstbyte_viol\n";
'

